toad_implementation.code_blueprint:
canvas {
  size: 800px 800px;
  fill: #F4EAD4;
  font-family: "Bungee, cursive";
}

>rustRed = #D14935;
>slate = #2B3A41;
>mustard = #E9B44C;
>cream = #F4EAD4;

rect #badgeShadow {
  at: center of canvas offset 6px 6px;
  size: 380px 380px;
  fill: >slate;
  radius: 24px;
}

rect #badgeMain {
  at: center of canvas;
  size: 380px 380px;
  fill: >rustRed;
  stroke: >slate;
  stroke-width: 6px;
  radius: 24px;
}

circle #innerDecoRing {
  at: center of #badgeMain;
  size: 300px;
  fill: none;
  stroke: >mustard;
  stroke-width: 4px;
}

text #brandHero {
  at: center of #innerDecoRing offset 0px -20px;
  content: "RUSTY'S";
  font-size: 52px;
  font-weight: 900;
  color: >cream;
}

text #brandSubtitle {
  at: below #brandHero offset 8px;
  content: "CUSTOM MOTORCYCLE CO.";
  font-size: 13px;
  font-weight: 700;
  color: >mustard;
}

text #estBadge {
  at: below #brandSubtitle offset 20px;
  content: "★  EST. 1968  ★";
  font-size: 12px;
  font-weight: 700;
  color: >cream;
}
